SELECT COUNT(1) FROM order_ticket o

    INNER JOIN show_schedule s ON s.show_id = o.show_id

WHERE 1 = 1

    AND s.cinema_id = #{cinemaId}


    AND o.user_id = #{userId}


    AND o.status = #{status}


    AND CAST(o.created_at AS DATE) >= #{dateFrom}


    AND CAST(o.created_at AS DATE) <= #{dateTo}

SELECT COUNT(1) FROM order_ticket o

    INNER JOIN show_schedule s ON s.show_id = o.show_id

WHERE 1 = 1

    AND s.cinema_id = #{cinemaId}


    AND o.user_id = #{userId}


    AND o.status = #{status}


    AND o.created_at >= CAST(#{dateFrom} AS timestamp)


    AND o.created_at < (CAST(#{dateTo} AS timestamp) + INTERVAL '1 day')

SELECT o.order_id, o.user_id, o.show_id, o.lock_id, o.movie_title, o.cinema_name, o.hall_name,
       o.start_time, o.seat_ids_json, o.unit_price, o.amount, o.seat_price_snapshot, o.status,
       o.ticket_code, o.qr_payload, o.pay_channel, o.expire_at, o.pay_at, o.cancel_reason,
       o.session_id, o.created_at, o.updated_at
FROM order_ticket o

    INNER JOIN show_schedule s ON s.show_id = o.show_id

WHERE 1 = 1

    AND s.cinema_id = #{cinemaId}


    AND o.user_id = #{userId}


    AND o.status = #{status}


    AND CAST(o.created_at AS DATE) >= #{dateFrom}


    AND CAST(o.created_at AS DATE) <= #{dateTo}

ORDER BY o.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT o.order_id, o.user_id, o.show_id, o.lock_id, o.movie_title, o.cinema_name, o.hall_name, o.start_time, o.seat_ids_json, o.unit_price, o.amount, o.seat_price_snapshot, o.status, o.ticket_code, o.qr_payload, o.pay_channel, o.expire_at, o.pay_at, o.cancel_reason, o.session_id, o.created_at, o.updated_at FROM order_ticket o
INNER JOIN show_schedule s ON s.show_id = o.show_id
WHERE 1 = 1
AND s.cinema_id = #{cinemaId}
AND o.user_id = #{userId}
AND o.status = #{status}
AND o.created_at >= CAST(#{dateFrom} AS timestamp)
AND o.created_at < (CAST(#{dateTo} AS timestamp) + INTERVAL '1 day')
ORDER BY o.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT order_id FROM order_ticket
WHERE status = 'pending_pay'
  AND expire_at IS NOT NULL
  AND expire_at < #{now}
ORDER BY expire_at ASC
LIMIT #{limit}
